{
  "root": "main_stack",
  "state": {
    "sentiment_data": [
      { "sentiment": "Positive", "percentage": 64.3, "responses": 450 },
      { "sentiment": "Neutral", "percentage": 25.7, "responses": 180 },
      { "sentiment": "Negative", "percentage": 10.0, "responses": 70 }
    ],
    "feature_mentions_data": [
      { "feature": "Feature A", "mentions": 300 },
      { "feature": "Feature B", "mentions": 150 },
      { "feature": "Feature C", "mentions": 100 }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": [
        "header_stack",
        "intro_text",
        "divider_1",
        "sentiment_features_section",
        "divider_2",
        "quick_actions_section"
      ]
    },
    "header_stack": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "sm", "align": "center" },
      "children": ["header_icon", "header_title"]
    },
    "header_icon": {
      "type": "Icon",
      "props": { "name": "../assets/r_000642_01_1_speedometer2.svg" },
      "children": []
    },
    "header_title": {
      "type": "Text",
      "props": { "text": "Product Launch Customer Feedback Dashboard", "variant": "h1" },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": { "text": "This dashboard summarizes initial customer feedback for your recent product launch, highlighting sentiment trends and key feature engagement.", "variant": "body" },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "sentiment_features_section": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md" },
      "children": [
        "sentiment_features_header_stack",
        "sentiment_features_intro_text",
        "sentiment_chart_card",
        "feature_mentions_chart_card",
        "key_insights_card"
      ]
    },
    "sentiment_features_header_stack": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "sm", "align": "center" },
      "children": ["sentiment_features_icon", "sentiment_features_title"]
    },
    "sentiment_features_icon": {
      "type": "Icon",
      "props": { "name": "../assets/r_000642_01_2_bar-chart.svg" },
      "children": []
    },
    "sentiment_features_title": {
      "type": "Text",
      "props": { "text": "Sentiment Distribution and Feature Mentions", "variant": "h2" },
      "children": []
    },
    "sentiment_features_intro_text": {
      "type": "Text",
      "props": { "text": "Here's a breakdown of customer sentiment and specific feature mentions, presented as data for visualization.", "variant": "body" },
      "children": []
    },
    "sentiment_chart_card": {
      "type": "Card",
      "props": {},
      "children": ["sentiment_chart_header_stack", "sentiment_chart"]
    },
    "sentiment_chart_header_stack": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "sm", "align": "center" },
      "children": ["sentiment_chart_icon", "sentiment_chart_title"]
    },
    "sentiment_chart_icon": {
      "type": "Icon",
      "props": { "name": "../assets/r_000642_01_3_pie-chart.svg" },
      "children": []
    },
    "sentiment_chart_title": {
      "type": "Text",
      "props": { "text": "Customer Sentiment Distribution", "variant": "h3" },
      "children": []
    },
    "sentiment_chart": {
      "type": "Chart",
      "props": {
        "chartType": "pie",
        "title": "Customer Feedback Sentiment",
        "statePath": "/sentiment_data",
        "xKey": "sentiment",
        "yKey": "percentage",
        "columns": [
          { "key": "sentiment", "label": "Sentiment" },
          { "key": "percentage", "label": "Percentage" },
          { "key": "responses", "label": "Responses" }
        ]
      },
      "children": []
    },
    "feature_mentions_chart_card": {
      "type": "Card",
      "props": {},
      "children": ["feature_mentions_header_stack", "feature_mentions_chart"]
    },
    "feature_mentions_header_stack": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "sm", "align": "center" },
      "children": ["feature_mentions_icon", "feature_mentions_title"]
    },
    "feature_mentions_icon": {
      "type": "Icon",
      "props": { "name": "../assets/r_000642_01_4_bar-chart-line.svg" },
      "children": []
    },
    "feature_mentions_title": {
      "type": "Text",
      "props": { "text": "Feature Mention Frequency", "variant": "h3" },
      "children": []
    },
    "feature_mentions_chart": {
      "type": "Chart",
      "props": {
        "chartType": "bar",
        "title": "Product Feature Mentions",
        "statePath": "/feature_mentions_data",
        "xKey": "feature",
        "yKey": "mentions",
        "columns": [
          { "key": "feature", "label": "Feature" },
          { "key": "mentions", "label": "Mentions" }
        ]
      },
      "children": []
    },
    "key_insights_card": {
      "type": "Card",
      "props": {},
      "children": ["key_insights_title", "insight_1", "insight_2"]
    },
    "key_insights_title": {
      "type": "Text",
      "props": { "text": "Key Insights", "variant": "h3" },
      "children": []
    },
    "insight_1": {
      "type": "Text",
      "props": { "text": "• The product launch has been largely successful, with nearly two-thirds of customer feedback being positive. This indicates a strong initial reception.", "variant": "body" },
      "children": []
    },
    "insight_2": {
      "type": "Text",
      "props": { "text": "• Feature A is the most discussed and likely most impactful feature, receiving twice as many mentions as Feature B and three times as many as Feature C. This suggests it's a primary driver of user engagement or satisfaction.", "variant": "body" },
      "children": []
    },
    "divider_2": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "quick_actions_section": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md" },
      "children": ["quick_actions_title", "quick_actions_buttons_stack"]
    },
    "quick_actions_title": {
      "type": "Text",
      "props": { "text": "Quick Actions", "variant": "h2" },
      "children": []
    },
    "quick_actions_buttons_stack": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "md", "wrap": "wrap" },
      "children": ["share_dashboard_button", "export_data_button"]
    },
    "share_dashboard_button": {
      "type": "Button",
      "props": { "label": "Share Dashboard" },
      "on": {
        "press": {
          "action": "openUrl",
          "params": { "url": "https://example.com/share-dashboard-link" }
        }
      },
      "children": []
    },
    "export_data_button": {
      "type": "Button",
      "props": { "label": "Export Data" },
      "on": {
        "press": {
          "action": "openUrl",
          "params": { "url": "https://example.com/export-feedback-data" }
        }
      },
      "children": []
    }
  }
}
